import numpy as np
import tensorcircuit as tc
import tensornetwork as tn

tc.set_backend('numpy')
tc.set_dtype('complex128')

def build(side):
    n=side*side
    c=tc.Circuit(n, split={"max_singular_values": 2})
    for r in range(side):
        for col in range(side):
            c.ry(r*side+col, theta=0.2+0.03*r+0.02*col)
    for r in range(side):
        for col in range(side-1):
            c.rzz(r*side+col, r*side+col+1, theta=0.31+0.01*(r*side+col))
    for r in range(side-1):
        for col in range(side):
            c.rxx(r*side+col, (r+1)*side+col, theta=0.27+0.01*(r*side+col))
    for r in range(side):
        for col in range(side):
            c.rx(r*side+col, theta=0.17+0.01*r-0.01*col)
    return c

c=build(3)
nodes, fronts = c._copy()
print('copied', len(nodes), 'fronts', len(fronts))

# Identify bridge edges: edges connecting two 3-legged nodes (split bonds)
bridges=[]
seen=set()
for n in nodes:
    if len(n.edges)!=3:
        continue
    for e in n.edges:
        if e.is_dangling():
            continue
        a,b=e.node1,e.node2
        if a is None or b is None:
            continue
        if len(a.edges)==3 and len(b.edges)==3:
            eid=id(e)
            if eid not in seen:
                seen.add(eid)
                bridges.append(e)
print('bridges', len(bridges))
# expected 3x3: horiz 3*2=6, vert 2*3=6, total 12
print('bridge dims', [e.dimension for e in bridges])

# disconnect bridges by creating dangling? tensornetwork may not allow easy cut.
# Instead, assign nodes to sites by not traversing bridges.

from collections import defaultdict, deque
node_site = {}
# start from each front
for q, fe in enumerate(fronts):
    start = fe.node1 if fe.node1 is not None else fe.node2
    dq=deque([start])
    while dq:
        n=dq.popleft()
        if n is None or n in node_site:
            continue
        node_site[n]=q
        for e in n.edges:
            if e.is_dangling():
                continue
            # skip bridges
            if e in bridges or id(e) in seen:
                continue
            other = e.node2 if e.node1 is n else e.node1
            if other is not None and other not in node_site:
                dq.append(other)

print('assigned', len(node_site), 'of', len(nodes))
from collections import Counter
print(Counter(node_site.values()))
# unassigned?
unas=[n for n in nodes if n not in node_site]
print('unassigned', len(unas), [ (n.name, tuple(e.dimension for e in n.edges)) for n in unas])
