for r in range(side):
    for col in range(side):
        c.ry(r*side+col, theta=0.2+0.03*r+0.02*col)
for r in range(side):
    for col in range(side-1):
        c.rzz(r*side+col, r*side+col+1, theta=0.31+0.01*(r*side+col))
for r in range(side-1):
    for col in range(side):
        c.rxx(r*side+col, (r+1)*side+col, theta=0.27+0.01*(r*side+col))
for r in range(side):
    for col in range(side):
        c.rx(r*side+col, theta=0.17+0.01*r-0.01*col)

print('nnodes', len(c._nodes))
for i,node in enumerate(c._nodes):
    shape=tuple(e.dimension for e in node.edges)
    conns=[]
    for ei,e in enumerate(node.edges):
        other = e.node2 if e.node1 is node else e.node1
        if other is None:
            conns.append(f'{ei}:DANG')
        else:
            try:
                j=c._nodes.index(other)
